        ForEach-Object { [CompletionResult]::new($_, $_, 'ParameterName', $_) }
}
"""
    return None

class Opts:
    def __init__(self):
        self.output=None; self.test=None; self.test_file=None; self.repl=False; self.no_color=False; self.gen=None; self.input=[]

def cli_error(msg, usage=None):
    sys.stderr.write('error: ' + msg + '\n\n')
    if usage:
        sys.stderr.write('Usage: ' + usage + '\n\n')
    sys.stderr.write("For more information, try '--help'.\n")
    return 2

def parse_args(argv):
    o = Opts(); i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            o.input.extend(argv[i+1:]); break
        if a in ('-h','--help'):
            sys.stdout.write(HELP); return None, 0
        if a in ('-V','--version'):
            sys.stdout.write(VERSION); return None, 0
        def need(name, display):
            nonlocal i
            if i+1 >= len(argv):
                return None, cli_error(f"a value is required for '{display}' but none was supplied")
            i += 1
            return argv[i], None
        if a in ('-n','--no-color'):
            o.no_color=True
        elif a in ('-r','--repl'):
            o.repl=True
        elif a in ('-o','--output'):
            v,e=need(a, '--output <OUTPUT_FILE_PATH>')
            if e is not None: return None,e
            o.output=v
        elif a.startswith('--output='):
            o.output=a.split('=',1)[1]
        elif a in ('-t','--test'):
            v,e=need(a, '--test <test>')
            if e is not None: return None,e
            o.test=v
        elif a.startswith('--test='):
            o.test=a.split('=',1)[1]
        elif a in ('-f','--test-file'):
            v,e=need(a, '--test-file <test-file>')
            if e is not None: return None,e
            o.test_file=v
        elif a.startswith('--test-file='):
            o.test_file=a.split('=',1)[1]
        elif a == '--generate-completions':
            v,e=need(a, '--generate-completions <completions>')
            if e is not None: return None,e
            o.gen=v
        elif a.startswith('--generate-completions='):
            o.gen=a.split('=',1)[1]
        elif a.startswith('-'):
            sys.stderr.write(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n")
            return None,2
        else:
            o.input.append(a)
        i += 1
    if len(o.input) > 1:
        b=o.input[1]
        sys.stderr.write(f"error: unexpected argument '{b}' found\n\nUsage: executable [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n")
        return None,2
    # selected clap conflicts observed in the reference binary
    if o.test is not None and o.output is not None:
        return None, cli_error("the argument '--test <test>' cannot be used with '--output <OUTPUT_FILE_PATH>'", 'executable --test <test> <INPUT_FILE_PATH>')
    if o.test is not None and o.test_file is not None:
        return None, cli_error("the argument '--test <test>' cannot be used with '--test-file <test-file>'", 'executable --test <test> <INPUT_FILE_PATH>')
    if o.test_file is not None and o.output is not None:
        return None, cli_error("the argument '--test-file <test-file>' cannot be used with '--output <OUTPUT_FILE_PATH>'", 'executable --test-file <test-file> <INPUT_FILE_PATH>')
    if o.repl and o.test is not None:
        return None, cli_error("the argument '--repl' cannot be used with '--test <test>'", 'executable --repl <INPUT_FILE_PATH>')
    if o.repl and o.gen is not None:
        return None, cli_error("the argument '--repl' cannot be used with '--generate-completions <completions>'", 'executable --repl [INPUT_FILE_PATH]')
    return o, None

def read_source(path):
    if path is None or path == '-':
        return sys.stdin.read(), None
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return f.read(), None
    except Exception:
        return None, f"unable read file at path {path}"

def compile_for_python(regex):
    # Translate a couple of ECMAScript constructs into Python re equivalents for testing.
    r = regex.replace('\\0', '\\x00')
    r = re.sub(r'\(\?<([A-Za-z_]+)>', r'(?P<\1>', r)
    return r

def regex_reversed_range(regex):
    # Simple detector for the common generated [z-a] style invalid range.
    for m in re.finditer(r'\[\^?(.?)-(.?)\]', regex):
        a,b=m.group(1),m.group(2)
        if len(a)==1 and len(b)==1 and ord(a)>ord(b):
            return True
    return False

def do_test(regex, text):
    try:
        pyre = compile_for_python(regex)
        cre = re.compile(pyre)
        return cre.search(text) is not None, None
    except Exception:
        if regex_reversed_range(regex):
            return None, "could not compile regex\nCause: range values reversed, start char code is greater than end char code.\nRegex: " + regex
        return None, "could not compile regex"

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    opts, code = parse_args(argv)
    if code is not None:
        return code
    if opts.gen is not None:
        out = completion(opts.gen)
        if out is None:
            sys.stderr.write(f"Unknown or unsupported shell: '{opts.gen}'\nTry one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'\n")
        else:
            sys.stdout.write(out)
        return 0
    if opts.repl:
        if (not sys.stdin.isatty()) or (not sys.stdout.isatty()):
            sys.stderr.write('Error: repl argument supplied with piped input or output\n')
            return 64
        sys.stdout.write('Melody REPL\n')
        return 0
    src, err = read_source(opts.input[0] if opts.input else None)
    if err:
        sys.stderr.write('Error: ' + err + '\n')
        return 65
    try:
        regex = compile_melody(src)
    except MelodyError as e:
        sys.stderr.write(format_parse_error(src, e))
        return 65
    if opts.test is not None:
        matched, e = do_test(regex, opts.test)
        if e:
            sys.stderr.write('Error: ' + e + '\n')
            return 65
        sys.stdout.write("'%s' %s\n" % (opts.test, 'matched' if matched else 'did not match'))
        return 0
    if opts.test_file is not None:
        try:
            with open(opts.test_file, 'r', encoding='utf-8') as f:
                text = f.read()
        except Exception:
            sys.stderr.write('Error: unable read file at path ' + opts.test_file + '\n')
            return 74
        matched, e = do_test(regex, text)
        if e:
            sys.stderr.write('Error: ' + e + '\n')
            return 65
        sys.stdout.write('%s %s\n' % (opts.test_file, 'matched' if matched else 'did not match'))
        return 0
    if opts.output is not None:
        try:
            with open(opts.output, 'w', encoding='utf-8') as f:
                f.write(regex)
        except Exception:
            sys.stderr.write('Error: ' + opts.output + '\n')
            return 74
        return 0
    sys.stdout.write(regex + '\n')
    return 0

if __name__ == '__main__':
    sys.exit(main())
