#!/usr/bin/env python3
import sys, os, re

HELP = """A CLI wrapping the Melody language compiler

Usage: executable [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
"""

VERSION = "melody_cli 0.20.0\n"

EXPECTED_ROOT = "expected root"
EXPECTED_ITEM = "expected literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"
EXPECTED_AFTER = "expected EOI, literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"

SYMBOLS = {
    'char': ('.', None),
    'space': (' ', '[^ ]'),
    'whitespace': ('\\s', '\\S'),
    'digit': ('\\d', '\\D'),
    'word': ('\\w', '\\W'),
    'boundary': ('\\b', '\\B'),
    'start': ('^', None),
    'end': ('$', None),
    'newline': ('\\n', '[^\\n]'),
    'tab': ('\\t', '[^\\t]'),
    'null': ('\\0', '[^\\0]'),
    'backspace': ('[\\b]', '[^\\b]'),
    'return': ('\\r', '[^\\r]'),
    'vertical': ('\\v', '[^\\v]'),
    'alphabetic': ('[a-zA-Z]', '[^a-zA-Z]'),
    'alphanumeric': ('[a-zA-Z0-9]', '[^a-zA-Z0-9]'),
}

REGEX_META = set('.*+?^$()[]{}|')

class MelodyError(Exception):
    def __init__(self, msg=None, pos=None, expected=None):
        super().__init__(msg or expected or '')
        self.msg = msg
        self.pos = pos
        self.expected = expected

class Parser:
    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.i = 0

    def error(self, expected=EXPECTED_ROOT, pos=None):
        raise MelodyError(pos=self.i if pos is None else pos, expected=expected)

    def skip_ws(self):
        while self.i < self.n:
            c = self.s[self.i]
            if c.isspace():
                self.i += 1
                continue
            if self.s.startswith('//', self.i):
                self.i += 2
                while self.i < self.n and self.s[self.i] != '\n':
                    self.i += 1
                continue
            if self.s.startswith('/*', self.i):
                self.i += 2
                j = self.s.find('*/', self.i)
                if j < 0:
                    self.i = self.n
                else:
                    self.i = j + 2
                continue
            break

    def starts_word(self, word):
        self.skip_ws()
        if not self.s.startswith(word, self.i):
            return False
        end = self.i + len(word)
        if end < self.n and (self.s[end].isalpha() or self.s[end] == '_' or self.s[end].isdigit()):
            return False
        return True

    def consume_word(self, word):
        if self.starts_word(word):
            self.i += len(word)
            return True
        return False

    def require_word(self, word, expected=EXPECTED_ROOT):
        if not self.consume_word(word):
            self.error(expected)

    def parse_root(self):
        parts = []
        self.skip_ws()
        while self.i < self.n:
            parts.append(self.parse_expr(context='root').regex)
            self.skip_ws()
        return ''.join(parts)

    def parse_block_parts(self, kind):
        self.skip_ws()
        if self.i >= self.n or self.s[self.i] != '{':
            self.error('expected block')
        self.i += 1
        parts = []
        self.skip_ws()
        if self.i < self.n and self.s[self.i] == '}':
            # original reports at the closing brace for empty blocks
            self.error(EXPECTED_ITEM)
        while True:
            self.skip_ws()
            if self.i >= self.n:
                self.error(EXPECTED_ITEM)
            if self.s[self.i] == '}':
                self.i += 1
                break
            parts.append(self.parse_expr(context='block').regex)
            self.skip_ws()
        return parts

    def parse_expr(self, context='root'):
        self.skip_ws()
        if self.i >= self.n:
            self.error(EXPECTED_ROOT)
        start = self.i
        # quantifier prefixes must be checked before ranges (numbers) and normal words.
        q = self.try_parse_quantifier_prefix()
        if q is not None:
            kind, a, b = q
            atom = self.parse_quantified_target(context)
            return Node(self.apply_quant(atom, kind, a, b), True)
        if self.consume_word('not'):
            return self.parse_not(context)
        for word in ('match', 'capture', 'either', 'ahead', 'behind'):
            if self.starts_word(word):
                return self.parse_group_or_assert()
        c = self.s[self.i]
        if c in ('"', "'"):
            lit, char_count = self.parse_string()
            self.expect_semicolon()
            return Node(escape_literal(lit), char_count == 1)
        if c == '<':
            val, atom = self.parse_symbol(False)
            self.expect_semicolon()
            return Node(val, atom)
        rng = self.try_parse_range(False)
        if rng is not None:
            self.expect_semicolon()
            return Node(rng, True)
        self.error(EXPECTED_ROOT if context == 'root' else 'expected quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration', start)

    def try_parse_quantifier_prefix(self):
        self.skip_ws()
        save = self.i
        # numeric exact/range quantity
        if self.i < self.n and self.s[self.i].isdigit():
            j = self.i
            while j < self.n and self.s[j].isdigit():
                j += 1
            a = self.s[self.i:j]
            self.i = j
            self.skip_ws()
            b = None
            if self.consume_word('to'):
                self.skip_ws()
                k = self.i
                while k < self.n and self.s[k].isdigit():
                    k += 1
                if k == self.i:
                    self.error('expected amount', self.i)
                b = self.s[self.i:k]
                self.i = k
                self.skip_ws()
            if self.consume_word('of'):
                return ('range' if b is not None else 'exact', a, b)
            self.i = save
            return None
        for w, k in (('some','some'),('any','any'),('option','option')):
            if self.consume_word(w):
                self.skip_ws()
                if self.consume_word('of'):
                    return (k, None, None)
                self.i = save
                return None
        return None

    def parse_quantified_target(self, context):
        self.skip_ws()
        if self.consume_word('not'):
            return self.parse_not(context, in_quant=True)
        for word in ('match', 'capture', 'either', 'ahead', 'behind'):
            if self.starts_word(word):
                return self.parse_group_or_assert()
        c = self.s[self.i] if self.i < self.n else ''
        if c in ('"', "'"):
            lit, char_count = self.parse_string()
            self.expect_semicolon()
            return Node(escape_literal(lit), char_count == 1)
        if c == '<':
            val, atom = self.parse_symbol(False)
            self.expect_semicolon()
            return Node(val, atom)
        rng = self.try_parse_range(False)
        if rng is not None:
            self.expect_semicolon()
            return Node(rng, True)
        self.error('expected literal, not, range, group_declaration, assertion_declaration, or variable_declaration')

    def apply_quant(self, atom, kind, a, b):
        suffix = {'some': '+', 'any': '*', 'option': '?'}.get(kind)
        if kind == 'exact':
            suffix = '{%s}' % a
        elif kind == 'range':
            suffix = '{%s,%s}' % (a, b)
        base = atom.regex if atom.atomic else '(?:%s)' % atom.regex
        return base + suffix

    def parse_not(self, context, in_quant=False):
        self.skip_ws()
        if self.starts_word('ahead') or self.starts_word('behind'):
            word = 'ahead' if self.starts_word('ahead') else 'behind'
            self.i += len(word)
            parts = self.parse_block_parts(word)
            inner = ''.join(parts)
            return Node(('(?!%s)' if word == 'ahead' else '(?<!%s)') % inner, True)
        if self.i < self.n and self.s[self.i] == '<':
            val, atom = self.parse_symbol(True)
            self.expect_semicolon()
            return Node(val, atom)
        rng = self.try_parse_range(True)
        if rng is not None:
            self.expect_semicolon()
            return Node(rng, True)
        self.error('expected amount, class_content, or assertion_type' if not in_quant else 'expected amount or assertion_type')

    def parse_group_or_assert(self):
        if self.consume_word('match'):
            inner = ''.join(self.parse_block_parts('match'))
            return Node('(?:%s)' % inner, True)
        if self.consume_word('either'):
            alts = self.parse_block_parts('either')
            return Node('(?:%s)' % '|'.join(alts), True)
        if self.consume_word('capture'):
            self.skip_ws()
            name = None
            if self.i < self.n and self.s[self.i] != '{':
                name = self.parse_identifier()
                if name is None:
                    self.error('expected block or identifier')
            parts = self.parse_block_parts('capture')
            inner = ''.join(parts)
            if name is None:
                return Node('(%s)' % inner, True)
            return Node('(?<%s>%s)' % (name, inner), True)
        if self.consume_word('ahead'):
            inner = ''.join(self.parse_block_parts('ahead'))
            return Node('(?=%s)' % inner, True)
        if self.consume_word('behind'):
            inner = ''.join(self.parse_block_parts('behind'))
            return Node('(?<=%s)' % inner, True)
        self.error(EXPECTED_ROOT)

    def parse_identifier(self):
        self.skip_ws()
        j = self.i
        if j < self.n and (self.s[j].isalpha() or self.s[j] == '_'):
            j += 1
            while j < self.n and (self.s[j].isalpha() or self.s[j] == '_'):
                j += 1
            name = self.s[self.i:j]
            self.i = j
            return name
        return None

    def parse_string(self):
        self.skip_ws()
        quote = self.s[self.i]
        self.i += 1
        out = []
        count = 0
        while self.i < self.n:
            c = self.s[self.i]
            if c == quote:
                self.i += 1
                return ''.join(out), count
            if c == '\\':
                if self.i + 1 >= self.n:
                    self.error(EXPECTED_ROOT)
                n = self.s[self.i+1]
                if n == quote or n == '\\':
                    out.append(n); count += 1; self.i += 2; continue
                if n in ('n','t','r'):
                    out.append('\\' + n); count += 2; self.i += 2; continue
                if n == 'u' and self.i + 5 < self.n and all(ch in '0123456789abcdefABCDEF' for ch in self.s[self.i+2:self.i+6]):
                    out.append(self.s[self.i:self.i+6]); count += 6; self.i += 6; continue
                self.error(EXPECTED_ROOT, self.i if False else self.i - (1 if self.i>0 else 0))
            out.append(c); count += 1; self.i += 1
        self.error(EXPECTED_ROOT, 0)

    def parse_symbol(self, neg):
        self.skip_ws()
        start = self.i
        if self.i >= self.n or self.s[self.i] != '<':
            self.error(EXPECTED_ROOT)
        j = self.s.find('>', self.i+1)
        if j < 0:
            self.error(EXPECTED_ROOT, start)
        name = self.s[self.i+1:j]
        # Names with dashes do not reach the symbol table in the original grammar.
        if '-' in name or not name:
            self.error(EXPECTED_ROOT, start)
        self.i = j + 1
        if name not in SYMBOLS:
            raise MelodyError(msg='usage of an unrecognized symbol')
        val, negval = SYMBOLS[name]
        if neg:
            if negval is None:
                raise MelodyError(msg='negative %s not allowed' % name)
            val = negval
        return val, True

    def try_parse_range(self, neg):
        self.skip_ws()
        save = self.i
        if save >= self.n:
            return None
        # A Melody range is a single non-space ASCII character, the word "to", then another.
        c1 = self.s[self.i]
        if c1.isspace() or c1 in '"\'{}<>;/':
            return None
        if ord(c1) > 127:
            return None
        self.i += 1
        self.skip_ws()
        if not self.consume_word('to'):
            self.i = save
            return None
        self.skip_ws()
        if self.i >= self.n:
            self.i = save
            return None
        c2 = self.s[self.i]
        if c2.isspace() or c2 in '"\'{}<>;/':
            self.i = save
            return None
        if ord(c2) > 127:
            self.i = save
            return None
        self.i += 1
        content = range_char(c1) + '-' + range_char(c2)
        if neg:
            return '[^%s]' % content
        return '[%s]' % content

    def expect_semicolon(self):
        self.skip_ws()
        if self.i < self.n and self.s[self.i] == ';':
            self.i += 1
            return
        self.error(EXPECTED_ROOT)

class Node:
    def __init__(self, regex, atomic):
        self.regex = regex
        self.atomic = atomic

def range_char(c):
    if c in '\\]^-':
        # The original leaves '-' alone in most positions; escaping is safer for edge cases.
        return '\\' + c if c != '-' else '-'
    return c

def escape_literal(s):
    return ''.join(('\\' + c) if c in REGEX_META else c for c in s)

def line_col(text, pos):
    if pos < 0: pos = 0
    if pos > len(text): pos = len(text)
    line = text.count('\n', 0, pos) + 1
    last = text.rfind('\n', 0, pos)
    col = pos - last
    return line, col

def format_parse_error(text, err):
    if err.msg:
        return 'Error: ' + err.msg + '\n'
    pos = 0 if err.pos is None else err.pos
    line, col = line_col(text, pos)
    lines = text.splitlines()
    if not lines:
        src_line = ''
    elif line-1 < len(lines):
        src_line = lines[line-1]
    else:
        src_line = ''
    expected = err.expected or EXPECTED_ROOT
    return f"Error:  --> {line}:{col}\n  |\n{line} | {src_line}\n  | {' '*(col-1)}^---\n  |\n  = {expected}\n"

def compile_melody(src):
    return Parser(src).parse_root()

def completion(shell):
