        elif a.startswith('--output='):
            o.output=a.split('=',1)[1]
        elif a in ('-t','--test'):
            v,e=need(a, '--test <test>')
            if e is not None: return None,e
            o.test=v
        elif a.startswith('--test='):
            o.test=a.split('=',1)[1]
        elif a in ('-f','--test-file'):
            v,e=need(a, '--test-file <test-file>')
            if e is not None: return None,e
            o.test_file=v
        elif a.startswith('--test-file='):
            o.test_file=a.split('=',1)[1]
        elif a == '--generate-completions':
            v,e=need(a, '--generate-completions <completions>')
            if e is not None: return None,e
            o.gen=v
        elif a.startswith('--generate-completions='):
            o.gen=a.split('=',1)[1]
        elif a.startswith('-'):
            sys.stderr.write(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.\n")
            return None,2
        else:
            o.input.append(a)
        i += 1
    if len(o.input) > 1:
        b=o.input[1]
